def available_copies(repo: Repository, book_id: str) -> int:
    """在架副本数，只统计 `on_shelf` 的副本。

    实现: DATA-001
    """
    return sum(1 for copy in repo.copies_of(book_id) if copy.status is CopyStatus.ON_SHELF)

def parse_bool(params: Mapping[str, str], name: str) -> bool | None:
    """解析布尔查询参数；参数没有出现时返回 None。

    实现: API-003
    """
    if name not in params:
        return None
    value = params[name].strip().lower()
    if value in _TRUE_VALUES:
        return True
    if value in _FALSE_VALUES:
        return False
    raise InvalidParameter(name, f"{name} 只能是 true、false、1 或 0")

class LibraryApp:
    """WSGI 入口。

    实现: API-001, API-002
    """

    def __init__(self, repo: Repository, clock: Clock) -> None:
        self.context = AppContext(repo=repo, clock=clock)

    def __call__(self, environ: dict, start_response: Callable) -> Iterable[bytes]:
        length = int(environ.get("CONTENT_LENGTH") or 0)
        request = Request(
            method=environ.get("REQUEST_METHOD", "GET").upper(),
            path=environ.get("PATH_INFO", "/") or "/",
            query=parse_query(environ.get("QUERY_STRING", "")),
            body=environ["wsgi.input"].read(length) if length else b"",
        )
        try:
            status, payload = self.dispatch(request)
        except LibraryError as exc:
            status, payload = exc.status, exc.to_dict()
        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        start_response(
            f"{status} {HTTPStatus(status).phrase}",
            [("Content-Type", "application/json; charset=utf-8"), ("Content-Length", str(len(body)))],
        )
        return [body]

    def dispatch(self, request: Request) -> tuple[int, dict]:
        for method, pattern, handler in ROUTES:
            match = pattern.fullmatch(request.path)
            if match and method == request.method:
                return handler(self.context, request, **match.groupdict())
        raise NotFound(f"没有这个接口：{request.method} {request.path}")

class LibraryError(Exception):
    """所有业务错误的基类。

    实现: API-002
    """

    status = 500
    code = "internal_error"

    def __init__(self, message: str, *, field: str | None = None) -> None:
        super().__init__(message)
        self.message = message
        self.field = field

    def to_dict(self) -> dict:
        return {"error": {"code": self.code, "message": self.message, "field": self.field}}

def overdue_fine_cents(due_on: date, returned_on: date, price_cents: int) -> int:
    """按逾期天数计算罚款（单位：分），不超过图书定价。

    实现: FINE-001, FINE-002, FINE-003
    """
    days_late = (returned_on - due_on).days
    if days_late <= 0:
        return 0
    return min(days_late * FINE_PER_DAY_CENTS, price_cents)

